import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.DP3MvGHK.js";const u=JSON.parse('{"title":"CLI Options","description":"","frontmatter":{"outline":[4]},"headers":[],"relativePath":"reference/cli-options.md","filePath":"reference/cli-options.md"}'),n={name:"reference/cli-options.md"};function i(s,e,c,l,d,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="cli-options" tabindex="-1">CLI Options <a class="header-anchor" href="#cli-options" aria-label="Permalink to &quot;CLI Options&quot;">​</a></h1><h3 id="clioptions" tabindex="-1">CliOptions <a class="header-anchor" href="#clioptions" aria-label="Permalink to &quot;CliOptions&quot;">​</a></h3><p>A configuration object may be provided in the class constructor. The available options are:</p><h4 id="hooks" tabindex="-1"><code>hooks</code> <a class="header-anchor" href="#hooks" aria-label="Permalink to &quot;`hooks`&quot;">​</a></h4><p>Lifecycle hooks triggered when using <code>Cli.run()</code>:</p><ul><li><code>afterParse</code>: executed after argument-parsing.</li><li><code>beforeExecute</code>: when an action/script is found to execute, this is invoked right before.</li><li><code>afterExecute</code>: after the action/script is executed. If an error is generated during execution, will be included as part of the arguments. <strong>Default</strong>: <code>{}</code></li></ul><h4 id="baselocation" tabindex="-1"><code>baseLocation</code> <a class="header-anchor" href="#baselocation" aria-label="Permalink to &quot;`baseLocation`&quot;">​</a></h4><p>Base path where the <code>ProcessingOutput.location</code> will start from.<br><strong>Default</strong>: <code>path.dirname(entryFile)</code></p><h4 id="basescriptlocation" tabindex="-1"><s><code>baseScriptLocation</code></s> <a class="header-anchor" href="#basescriptlocation" aria-label="Permalink to &quot;~~`baseScriptLocation`~~&quot;">​</a></h4><p>Base path where the <code>ProcessingOutput.location</code> will start from.<br><strong>Default</strong>: <code>path.dirname(entryFile)</code></p><blockquote><p><strong>Warning: deprecated since 0.13.0 in favor of <code>CliOptions.baseLocation</code></strong></p></blockquote><h4 id="commandspath" tabindex="-1"><code>commandsPath</code> <a class="header-anchor" href="#commandspath" aria-label="Permalink to &quot;`commandsPath`&quot;">​</a></h4><p>Path where the single-command scripts (not contained in any namespace) are stored. A relative value can be provided, using <code>CliOptions.baseLocation</code> as base path.<br><strong>Default</strong>: <code>&quot;commands&quot;</code></p><h4 id="errors" tabindex="-1"><code>errors</code> <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;`errors`&quot;">​</a></h4><p>Configuration related to when errors should be displayed. The order of the lists containing the error-types matters, as it changes which error-messages are shown first (elements appearing first have a higher order of precedence). The available error-types are:</p><ul><li><code>command_not_found</code>: an unknown argument is encountered when a command was expected</li><li><code>option_wrong_value</code>: the option parser considers the given value as incorrect (e.g. <code>type:number</code> when given <code>&quot;a123&quot;</code>)</li><li><code>option_required</code>: an option is marked as required but is not provided</li><li><code>option_missing_dependencies</code>: some requirement specified for an option (<code>Option.requires</code>) is missing.</li><li><code>option_missing_value</code>: an option is provided without its corresponding value</li><li><code>option_not_found</code>: an unknown argument is encountered when an option was expected</li></ul><h5 id="errors-ongeneratehelp" tabindex="-1"><code>errors.onGenerateHelp</code> <a class="header-anchor" href="#errors-ongeneratehelp" aria-label="Permalink to &quot;`errors.onGenerateHelp`&quot;">​</a></h5><p>List of error-types that will get displayed before help<br><strong>Default</strong>: <code>[&quot;command_not_found&quot;]</code></p><h5 id="errors-onexecutecommand" tabindex="-1"><code>errors.onExecuteCommand</code> <a class="header-anchor" href="#errors-onexecutecommand" aria-label="Permalink to &quot;`errors.onExecuteCommand`&quot;">​</a></h5><p>List of error-types that will cause to end execution with <code>exit(1)</code> <br><strong>Default</strong>: <code>[&quot;command_not_found&quot;, &quot;option_wrong_value&quot;, &quot;option_required&quot;, &quot;option_missing_value&quot;, &quot;option_missing_dependencies&quot;, &quot;option_not_found&quot;]</code></p><h4 id="help" tabindex="-1"><code>help</code> <a class="header-anchor" href="#help" aria-label="Permalink to &quot;`help`&quot;">​</a></h4><p>Help-related configuration</p><h5 id="help-autoinclude" tabindex="-1"><code>help.autoInclude</code> <a class="header-anchor" href="#help-autoinclude" aria-label="Permalink to &quot;`help.autoInclude`&quot;">​</a></h5><p>Whether to generate help option <br><strong>Default</strong>: <code>true</code></p><h5 id="help-aliases" tabindex="-1"><code>help.aliases</code> <a class="header-anchor" href="#help-aliases" aria-label="Permalink to &quot;`help.aliases`&quot;">​</a></h5><p>Aliases to be used for help option<br><strong>Default</strong>: <code>[&quot;h&quot;, &quot;help&quot;]</code></p><h5 id="help-description" tabindex="-1"><code>help.description</code> <a class="header-anchor" href="#help-description" aria-label="Permalink to &quot;`help.description`&quot;">​</a></h5><p>Description for the option</p><h5 id="help-template" tabindex="-1"><code>help.template</code> <a class="header-anchor" href="#help-template" aria-label="Permalink to &quot;`help.template`&quot;">​</a></h5><p>Template to be used when generating help. There are five distinct sections: <strong>usage</strong>, <strong>description</strong>, <strong>namespaces</strong>, <strong>commands</strong> and <strong>options</strong>. This can be used to include a header/footer, change the order of the sections, or remove a section altogether. If a section has no content, it will be removed along with any line-breaks that follow. You can see a use-case for this in the <a href="https://github.com/carloscortonc/cli-er/blob/develop/examples/docker/definition.js#L133" target="_blank" rel="noreferrer">docker example</a> <br><strong>Default</strong>: <code>\\n{usage}\\n{description}\\n{namespaces}\\n{commands}\\n{options}\\n</code></p><h4 id="version" tabindex="-1"><code>version</code> <a class="header-anchor" href="#version" aria-label="Permalink to &quot;`version`&quot;">​</a></h4><p>Version-related configuration</p><h5 id="version-autoinclude" tabindex="-1"><code>version.autoInclude</code> <a class="header-anchor" href="#version-autoinclude" aria-label="Permalink to &quot;`version.autoInclude`&quot;">​</a></h5><p>Whether to generate version option<br><strong>Default</strong>: <code>true</code></p><h5 id="version-aliases" tabindex="-1"><code>version.aliases</code> <a class="header-anchor" href="#version-aliases" aria-label="Permalink to &quot;`version.aliases`&quot;">​</a></h5><p>Aliases to be used for version option<br><strong>Default</strong>: <code>[&quot;v&quot;, &quot;version&quot;]</code></p><h5 id="version-description" tabindex="-1"><code>version.description</code> <a class="header-anchor" href="#version-description" aria-label="Permalink to &quot;`version.description`&quot;">​</a></h5><p>Description for the option</p><h4 id="rootcommand" tabindex="-1"><code>rootCommand</code> <a class="header-anchor" href="#rootcommand" aria-label="Permalink to &quot;`rootCommand`&quot;">​</a></h4><p>Whether the cli implements a root command (invocation with no additional namespaces/commands). If a string is provided, it will be used as the default command to execute <br><strong>Default</strong>: <code>true</code></p><h4 id="logger" tabindex="-1"><code>logger</code> <a class="header-anchor" href="#logger" aria-label="Permalink to &quot;`logger`&quot;">​</a></h4><p>Logger to be used by the cli. It contains two methods, <code>log</code> and <code>error</code>, that can be used to add a prefix to the log (e.g. &quot;error &quot;) or change the output color, as demonstrated in this <a href="https://github.com/carloscortonc/cli-er/blob/develop/examples/docker/docker.js#L8" target="_blank" rel="noreferrer">docker example</a>.<br><strong>Default</strong>: <a href="https://github.com/carloscortonc/cli-er/blob/develop/src/cli-logger.ts" target="_blank" rel="noreferrer">/src/cli-logger.ts</a></p><h4 id="cliname" tabindex="-1"><code>cliName</code> <a class="header-anchor" href="#cliname" aria-label="Permalink to &quot;`cliName`&quot;">​</a></h4><p>Cli name to be used instead of the one defined in package.json<br><strong>Default</strong>: <code>packageJson.name</code></p><h4 id="cliversion" tabindex="-1"><code>cliVersion</code> <a class="header-anchor" href="#cliversion" aria-label="Permalink to &quot;`cliVersion`&quot;">​</a></h4><p>Cli version to be used instead of the one defined in package.json<br><strong>Default</strong>: <code>packageJson.version</code></p><h4 id="clidescription" tabindex="-1"><code>cliDescription</code> <a class="header-anchor" href="#clidescription" aria-label="Permalink to &quot;`cliDescription`&quot;">​</a></h4><p>Cli description to be used instead of the one defined in package.json<br><strong>Default</strong>: <code>packageJson.description</code></p><h4 id="debug" tabindex="-1"><code>debug</code> <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;`debug`&quot;">​</a></h4><p>Enable debug mode. This is intended for the development phase of the cli. It will:</p><ul><li>Print verbose errors when a script in not found in the expected path during <a href="/cli-er/docs/reference/api#runargs"><code>Cli.run</code></a>.</li><li><strong>Print warnings for deprecated properties/methods</strong>, useful for detecting and applying these changes before updating to the next version.</li></ul><p>Its value can also be configured using an enviroment variable:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CLIER_DEBUG=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli.js</span></span></code></pre></div><p><strong>Default</strong>: <code>process.env.CLIER_DEBUG</code></p><h4 id="completion" tabindex="-1"><code>completion</code> <a class="header-anchor" href="#completion" aria-label="Permalink to &quot;`completion`&quot;">​</a></h4><p>Configure bash-completion functionality</p><h5 id="completion-enabled" tabindex="-1"><code>completion.enabled</code> <a class="header-anchor" href="#completion-enabled" aria-label="Permalink to &quot;`completion.enabled`&quot;">​</a></h5><p>Whether to create bash-completion command<br><strong>Default</strong>: <code>true</code></p><h5 id="completion-command" tabindex="-1"><code>completion.command</code> <a class="header-anchor" href="#completion-command" aria-label="Permalink to &quot;`completion.command`&quot;">​</a></h5><p>Name of the completion command <strong>Default</strong>: <code>generate-completions</code></p><h4 id="messages" tabindex="-1"><code>messages</code> <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;`messages`&quot;">​</a></h4><p>Object containing the messages to be used in the Cli, to override the default ones defined by this library. This enables internationalization and customization of cli-native messages. You can see a use-case in this <a href="/cli-er/docs/examples/intl-cli">intl-cli example</a><br><strong>Default</strong>: defined in <a href="https://github.com/carloscortonc/cli-er/blob/develop/src/cli-messages.ts" target="_blank" rel="noreferrer">/src/cli-messages.ts</a> and <a href="https://github.com/carloscortonc/cli-er/blob/develop/src/cli-errors.ts" target="_blank" rel="noreferrer">/src/cli-errors.ts</a></p><h4 id="configfile" tabindex="-1"><code>configFile</code> <a class="header-anchor" href="#configfile" aria-label="Permalink to &quot;`configFile`&quot;">​</a></h4><p>Enable configuration file processing</p><h5 id="configfile-names" tabindex="-1"><code>configFile.names</code> <a class="header-anchor" href="#configfile-names" aria-label="Permalink to &quot;`configFile.names`&quot;">​</a></h5><p>Names of config files to search for</p><h5 id="configfile-parse" tabindex="-1"><code>configFile.parse</code> <a class="header-anchor" href="#configfile-parse" aria-label="Permalink to &quot;`configFile.parse`&quot;">​</a></h5><p>Override default <code>JSON</code> parser. Receives the contents of such file (string), and the full path for the file found.</p><h4 id="envprefix" tabindex="-1"><code>envPrefix</code> <a class="header-anchor" href="#envprefix" aria-label="Permalink to &quot;`envPrefix`&quot;">​</a></h4><p>Configure a prefix for environment variables to be included as options</p>',70)])])}const g=o(n,[["render",i]]);export{u as __pageData,g as default};
